#include <cmath>
#include <iomanip>
#include <iostream>
#include "lcbinint/magnification/holonomic/adaptive_epoch.hpp"
int main(){using namespace lcbinint::holonomic_fused;constexpr double rho=1e-6,u0=9.846481110931334e-7,alpha=.5,tE=10.,s=.95,q=1e7;double x=-u0*sin(alpha),y=u0*cos(alpha);LensParams p{x,y,rho,q,s,true};AdaptiveConfig cfg;cfg.tol.mu_atol=1e-5;cfg.tol.mu_rtol=1e-5;for(int j=0;j<5;++j)cfg.tol.grad_rtol[j]=1e-5;cfg.with_jacobian=true;cfg.gradient_policy=GradientPolicy::ValueFirst;cfg.fold_maps=false;cfg.initial_level=8;cfg.gradient_adaptive=true;cfg.value_first_gradient_node_budget=8192;cfg.value_first_gradient_round_budget=16;cfg.gradient_adaptive_node_budget=8192;cfg.gradient_adaptive_round_budget=16;cfg.collect_diagnostics=true;AdaptiveWorkspace w;auto a=epoch_adaptive(p,.5,cfg,w);double t0=(-cos(alpha)*a.grad_mu[0]-sin(alpha)*a.grad_mu[1])/tE;std::cout<<std::setprecision(17)<<"mu="<<a.mu<<" err="<<a.estimated_abs_error_mu<<" conv="<<a.value_converged<<" stop="<<adaptive_stop_name(a.stop)<<" gstop="<<adaptive_stop_name(a.gradient_stop_reason)<<" nodes="<<a.stats.node_evaluations<<" panels="<<a.stats.panels<<" t0="<<t0<<" gerr=";for(double e:a.estimated_abs_error_grad)std::cout<<e<<',';std::cout<<" gconv=";for(bool z:a.grad_converged)std::cout<<z<<',';std::cout<<" q=";for(auto z:a.grad_quality)std::cout<<int(z)<<',';std::cout<<" ang="<<a.stats.angular_upgrades<<" errpass="<<a.stats.gradient_error_pass_mask<<"\n";}
